<template><div class="page-shell"><header class="page-header compact"><div><h1>消息</h1><p class="page-subtitle">平台发送给你的消息。</p></div></header><StateMessage v-if="state!=='ready'" :state="state" :message="message"/><section v-else class="message-list"><article v-for="item in messages" :key="item.id" class="message-item" :class="{unread:!item.readAt}"><div><h2>{{item.subject}}</h2><time>{{formatDate(item.publishedAt)}}</time></div><p>{{item.body}}</p><button v-if="!item.readAt" class="secondary-button" type="button" @click="read(item.id)"><Check :size="18"/><span>标记已读</span></button></article><p v-if="!messages.length" class="empty-state">暂时没有消息。</p></section></div></template>
<script>
import {Check} from 'lucide-vue'; import StateMessage from '../components/StateMessage.vue'; import {library} from '../library/client.js'; import {markMessageRead} from '../library/models.js'; import {problemMessage} from '../ui/problem-message.js';
export default{name:'MessagesView',components:{Check,StateMessage},data:()=>({state:'loading',message:'正在加载消息…',messages:[]}),async mounted(){try{this.messages=await library.messages();this.state='ready';}catch(problem){this.state='error';this.message=problemMessage(problem);}},methods:{formatDate(value){return new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(new Date(value));},async read(id){try{await library.markRead(id);this.messages=markMessageRead(this.messages,id,new Date().toISOString());}catch(problem){this.message=problemMessage(problem);}}}};
</script>
